// metrics.live: a live topic (snapshot-delta, latest).
// Generated by `pnpm nx g @app/generators:topic metrics.live`, then edited. Run
// `pnpm nx run contracts:api-docs` so the AsyncAPI document follows. An item never carries a
// write-only secret, and the ring is bounded by items and bytes (I-6).
//
// The newest point of every cluster and node series of a connection, and of the queues the
// subscription names, plus one status item. Keyed by series, so the hub coalesces a series to its
// newest value (`latest`). The topic follows the collector's rounds; it starts one on demand.
import { z } from 'zod';

import { ConnectionIdSchema } from '../brands.ts';
import { defineTopic } from '../kit/define-topic.ts';
import {
  MetricsStatusSchema,
  QUEUE_DEMAND_MAX,
  QueueRefSchema,
  SeriesRefSchema,
} from './metrics-types.ts';

/** The reserved key of the status item. A series key always starts with a metric id. */
export const METRICS_STATUS_KEY = '~status';

export const MetricsLiveParamsSchema = z.strictObject({
  cid: ConnectionIdSchema,
  /** Queues whose series are wanted. At most 50: the topic never follows a whole kind (I-7). */
  queues: z.array(QueueRefSchema).max(QUEUE_DEMAND_MAX),
});

export const MetricsLiveItemSchema = z.strictObject({
  /** The series key, or `~status`. */
  key: z.string().min(1).max(1024),
  /** The series; absent on the status item. */
  ref: SeriesRefSchema.optional(),
  /** Epoch ms and value of the newest point; absent on the status item. */
  t: z.number().int().nonnegative().optional(),
  v: z.number().optional(),
  approximate: z.boolean().optional(),
  /** Present on the status item only. */
  status: MetricsStatusSchema.optional(),
});

export const metricsLiveTopic = defineTopic({
  id: 'metrics.live',
  params: MetricsLiveParamsSchema,
  item: MetricsLiveItemSchema,
  qos: 'latest',
  flow: 'snapshot-delta',
  permission: 'broker.read',
  key: (item) => item.key,
  maxHz: 1,
  ring: { items: 1000, bytes: 1048576 },
});
